 *  - 其余（对象 / 数组 / 数字等）：循环引用安全的 JSON 序列化（不是 `"[object Object]"`）。 */
export function toolOutputText(output: unknown): string {
  if (typeof output === "string") return output;
  if (output === undefined) return "[没有正文]";
  if (output === null) return "null";
